звірки.умова:
ШАР_ВИМКНЕНО ? с2.дом.every(д => !д.підпис_питань)
      : с2.дом.every((д, i) => { const n = с2.картки[i].тексти_питань.length + с2.картки[i].чекають;
          return n ? (д.згорнуто && д.підпис_питань.endsWith(' · ' + n)
                      && д.підпис_питань.length > (' · ' + n).length && !/код/i.test(д.підпис_питань))
                   : !д.підпис_питань; })

await стор.evaluate(і => {
            const п = ОЦ.перелік, р = п.речі.find(х => х.ід === і);
            return р.фото === ОЦ.фото[0].ід && р.дотик && р.рамка.право > р.рамка.ліво
              && !!п.контекст.пікселі[і] && !!п.мініатюри[і];
          }, ід)

await стор.evaluate(([і, к]) => {
            const п = ОЦ.перелік, р = п.речі.find(х => х.ід === і), колір = п.довідник.кольори.find(х => String(х.код) === к);
            return !!колір && р.колір === колір.ключ && п.hex[і] === колір.hex;
          }, [ід, код])

await стор.evaluate(і => {
            const п = ОЦ.перелік, з = п.звіт.слова[п.звіт.слова.length - 1];
            return п.речі.find(р => р.ід === і).в_образі === true && з.змінено === 1 && з.спосіб === 'text'
              && п.звіт.дії.some(д => д.ід === і && д.спосіб === 'text') && document.getElementById('оц-слова-поле').value === '';
          }, ід)
